package com.jobpilot.config;import com.jobpilot.user.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;@Service public class CurrentUserService{private final UserRepository users;public CurrentUserService(UserRepository u){users=u;}public User get(){String email=SecurityContextHolder.getContext().getAuthentication().getName();return users.findByEmail(email).orElseThrow();}}
